// TC-159 | req_ids: REQ-029 | level: api | type: api | model: shopcheck@25673b2
// Boundary: order quantity exactly equal to available stock succeeds; one over is refused
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-159: Boundary: order quantity exactly equal to available stock succeeds; one over is refused', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  // reset_state step: satisfied by the automatic per-test reset
  const products: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const seededProduct = products[0];  // first active seeded product
  await api.get(`/api/products/${seededProduct.id}`);
  // Expected: Stock N recorded
  await loginAs('standard_user');  // endpoint requires an authenticated session
  const products2: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const boundedStock = products2.find((p) => p.stock >= 1 && p.stock <= 10);
  if (!boundedStock) throw new Error('no seeded product with stock in the 1-10 order-quantity range');
  await api.post('/api/orders', { data: { items: [{ product_id: boundedStock.id, quantity: boundedStock.stock }] } });
  // Expected: Order for N units succeeds; stock reduced to exactly 0; Stock reduced to exactly 0 (never negative)
  // reset_state step: satisfied by the automatic per-test reset
  const products3: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const boundedStock2 = products3.find((p) => p.stock >= 1 && p.stock < 10);
  if (!boundedStock2) throw new Error('no seeded product with stock in the 1-10 order-quantity range');
  const res = await api.post('/api/orders', { data: { items: [{ product_id: boundedStock2.id, quantity: boundedStock2.stock + 1 }] } });
  expect(res.status()).toBe(409);
  // Expected (full): Order for N+1 refused with 409; Stock unchanged at N in the N+1 case
});
